private void pop(final String descriptor) {
    Stack<String> stack = new Stack<>();
    int i = 0;
    while (i < descriptor.length()) {
        char c = descriptor.charAt(i);
        if (c == '(') {
            int balance = 1;
            while (balance > 0) {
                i++;
                if (descriptor.charAt(i) == '(') balance++;
                else if (descriptor.charAt(i) == ')') balance--;
            }
        } else {
            stack.pop();
        }
        i++;
    }
}

