import org.jgrapht.graph.DefaultEdge;
import org.jgrapht.graph.SimpleGraph;
import org.jgrapht.traverse.BreadthFirstIterator;
import org.jgrapht.traverse.DepthFirstIterator;

import java.util.*;

public class TourTransformer {

    /**
     * Transform from a Set representation to a graph path.
     * @param tour a set containing the edges of the tour
     * @param graph the graph
     * @return a graph path
     */
    protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
        if (tour.isEmpty() || graph == null) {
            return null;
        }

        V startVertex = null;
        for (E edge : tour) {
            V source = graph.getEdgeSource(edge);
            V target = graph.getEdgeTarget(edge);
            if (startVertex == null) {
                startVertex = source;
            } else if (!graph.containsEdge(startVertex, source) && !graph.containsEdge(startVertex, target)) {
                startVertex = source;
                break;
            }
        }

        if (startVertex == null) {
            return null;
        }

        List<E> pathEdges = new ArrayList<>();
        pathEdges.addAll(tour);

        GraphPath<V, E> path = new Walk<V, E>(graph, startVertex, startVertex, 0.0, pathEdges);
        return path;
    }
}

