private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    byte b = bb.get(i);
    if (b >= 0) {
        sb.append((char) b);
        return i + 1;
    } else {
        int octetCount = 0;
        if ((b & 0xF8) == 0xF0) {
            octetCount = 4;
        } else if ((b & 0xF0) == 0xE0) {
            octetCount = 3;
        } else if ((b & 0xE0) == 0xC0) {
