            ch = (char) ((ch << 6) | (b & 0x3F));
        }

        if ((b & 0xC0) != 0x80) {
            throw new IllegalArgumentException("Invalid UTF-8 sequence");
        }

        ch = (char) ((ch << 6) | (b & 0x3F));
        sb.append(ch);
        return i + octetCount;
    }
}

