import java.io.File;
import java.io.IOException;
import java.net.URL;
import java.net.URLClassLoader;
import java.util.Vector;

@SuppressWarnings("unchecked")
public static void addToClassPath(Vector<URL> cpV, String dir) {
    File jarDir = new File(dir);
    if (jarDir.exists() && jarDir.isDirectory()) {
        File[] jars = jarDir.listFiles((d, name) -> name.endsWith(".jar"));
        if (jars != null) {
            for (File jar : jars) {
                try {
                    cpV.add(jar.toURI().toURL());
                    URLClassLoader classLoader = (URLClassLoader) ClassLoader.getSystemClassLoader();
                    java.lang.reflect.Method method = URLClassLoader.class.getDeclaredMethod("addURL", URL.class);
                    method.setAccessible(true);
                    method.invoke(classLoader, jar.toURI().toURL());
                } catch (IOException | NoSuchMethodException | IllegalAccessException | InvocationTargetException e) {
                    e.printStackTrace();
                }
            }
        }
    }
}

