public static String applyRelativePath(String path, String relativePath) {
    StringBuilder fullPath = new StringBuilder();
    String[] pathComponents = path.split("/");
    String[] relativeComponents = relativePath.split("/");

    int i = 0;
    // Remove the common prefix
    while (i < pathComponents.length && i < relativeComponents.length && pathComponents[i].equals(relativeComponents[i])) {
        i++;
    }

    // Go up the directory tree for each remaining component in the relative path
    while (i < relativeComponents.length && relativeComponents[i].equals("..")) {
        if (fullPath.length() > 0) {
            fullPath.setLength(fullPath.lastIndexOf("/"));
        }
        i++;
    }

    // Append the remaining components from the relative path
    while (i < relativeComponents.length) {
        if (fullPath.length() > 0) {
            fullPath.append("/");
        }
        fullPath.append(relativeComponents[i]);
        i++;
    }

    return fullPath.toString();
}

