public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    for (int i = index; i < index + len; i++) {
        char c = str.charAt(i);
        if ((c & 0x7F) == c) {
            size++;
        } else if ((c & 0xE0) == 0xC0) {
            size += 2;
        } else if ((c & 0xF0) == 0xE0) {
            size += 3;
        } else if ((c & 0xF8) == 0xF0) {
            size += 4;
        } else {
            throw new IllegalArgumentException("Invalid UTF-8 character");
        }
    }
    return size;
}

