import java.io.IOException;
import java.io.InputStream;

public class VarintReader {

    /**
     * Read a raw Varint from the stream.
     */
    public long readRawVarint64(InputStream in) throws IOException {
        long result = 0;
        for (int shift = 0; shift < 64; shift += 7) {
            int b = in.read();
            if (b == -1) {
                throw new IOException("Expected Varint, but reached end of stream");
            }
            result |= ((long) (b & 0x7F)) << shift;
            if ((b & 0x80) == 0) {
                break;
            }
        }
        return result;
    }
}

