import java.io.IOException;

public class ProtocolMessageParser {
    private byte[] buffer;
    private int position;
    private int limit;

    public ProtocolMessageParser(byte[] buffer, int limit) {
        this.buffer = buffer;
        this.position = 0;
        this.limit = limit;
    }

    public int readTag() throws IOException {
        if (position >= limit) {
            return 0;
        }
        int firstByte = buffer[position++] & 0xFF;
        if (firstByte == 0) {
            throw new IOException("Unexpected EOF at position " + position);
        }
        return firstByte << 8 | bufferedRead();
    }

    private int bufferedRead() throws IOException {
        if (position >= limit) {
            throw new IOException("Unexpected EOF at position " + position);
        }
        return buffer[position++] & 0xFF;
    }
}

